@import "tailwindcss";
@config "../tailwind.config.ts";

/* Class-based dark mode — toggled by adding .dark to the root element */
@custom-variant dark (&:where(.dark, .dark *));

@layer base {
  :root {
    --font-mono: 'IBM Plex Mono', ui-monospace, monospace;
    --font-sans: 'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif;

    /* Syntax highlight token colors */
    --hl-key:  #2563eb;
    --hl-str:  #16a34a;
    --hl-bool: #9333ea;
    --hl-null: #9ca3af;
    --hl-num:  #d97706;

    /* Pane handle */
    --handle-color: rgb(243, 244, 246);
  }

  .dark {
    --hl-key:  #60a5fa;
    --hl-str:  #4ade80;
    --hl-bool: #c084fc;
    --hl-null: #6b7280;
    --hl-num:  #fbbf24;

    --handle-color: rgb(55, 65, 81);
  }

  html, body {
    height: 100%;
    overflow: hidden;
  }

  code, pre, .font-mono {
    font-family: var(--font-mono);
  }

  /* Thin scrollbars */
  ::-webkit-scrollbar { width: 4px; height: 4px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: #d1d5db; border-radius: 2px; }
  ::-webkit-scrollbar-thumb:hover { background: #9ca3af; }

  .dark ::-webkit-scrollbar-thumb { background: #4b5563; }
  .dark ::-webkit-scrollbar-thumb:hover { background: #6b7280; }

  :focus-visible { outline: 2px solid #3b82f6; outline-offset: 1px; }
}

@layer components {
  .pane-handle {
    width: 6px;
    flex-shrink: 0;
    position: relative;
    display: flex;
    align-items: stretch;
    justify-content: center;
    cursor: col-resize;
    background: transparent;
    z-index: 10;
  }

  .pane-handle-line {
    width: 1px;
    background: var(--handle-color);
    transition: background-color 0.15s ease, width 0.1s ease;
    flex: 1;
  }

  .pane-handle:hover .pane-handle-line {
    background: rgb(147, 197, 253);
    width: 2px;
  }

  .pane-handle.dragging .pane-handle-line {
    background: rgb(59, 130, 246);
    width: 2px;
  }

  .nav-tag-chevron  { transition: transform 150ms ease; }
  .response-chevron { transition: transform 150ms ease; }

  .nav-endpoint.active { position: relative; }
  .nav-endpoint.active::before {
    content: '';
    position: absolute;
    left: 0; top: 0; bottom: 0;
    width: 2px;
    background: #3b82f6;
    border-radius: 0 1px 1px 0;
  }
}